const $ = s => document.querySelector(s);
const app = $('#app'), modal = $('#modal');
let state, page='dashboard', cart=[], search='', category='', stockOnly=false;
let filters={};
let saleDraft={customer:'',discount:'0',paid:'',method:'dinheiro'};
const money=v=>new Intl.NumberFormat('pt-AO',{style:'currency',currency:'AOA',maximumFractionDigits:2}).format((v||0)/100);
const qty=v=>new Intl.NumberFormat('pt-AO',{maximumFractionDigits:3}).format(v||0);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>new Date(v.replace(' ','T')+'Z').toLocaleString('pt-AO',{dateStyle:'short',timeStyle:'medium',timeZone:'Africa/Luanda'});
const icons={eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',bag:'M5 7h14l2 14H3L5 7Z M9 8V6a3 3 0 0 1 6 0v2',box:'m3 7 9-4 9 4-9 4-9-4Z M3 7v10l9 4 9-4V7 M12 11v10 M7 5l10 4',chart:'M4 3v18h17 M8 16v-4 M13 16V8 M18 16V5',cash:'M3 5h18v14H3z M3 9h18 M7 15h3 M16 13v4',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-3-7 M21 3v6h-6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M22 21v-2a4 4 0 0 0-3-3.9 M16 3a4 4 0 0 1 0 8',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',out:'M9 5H4v14h5 M13 12h9 M18 8l4 4-4 4',close:'M6 6l12 12 M18 6 6 18',check:'m5 12 4 4L19 6',leaf:'M20 3C8 2 2 8 5 15s15 5 15-12Z M5 21 16 9',receipt:'M5 3h14v18l-3-2-4 2-4-2-3 2V3Z M8 7h8 M8 11h8 M8 15h4',barcode:'M3 4v16 M6 4v16 M10 4v16 M13 4v16 M17 4v16 M21 4v16',trend:'m3 17 6-6 4 4 8-10 M15 5h6v6',print:'M6 8V3h12v5 M6 17H3V8h18v9h-3 M6 13h12v8H6z'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.box}"/></svg>`;
const roleLabel={proprietario:'Proprietário',gerente:'Gerente',vendedor:'Vendedor'};
const methodLabel={dinheiro:'Dinheiro',transferencia:'Transferência',tpa:'TPA / Multicaixa'};
const manager=()=>state.user.role!=='vendedor';
const shift=()=>state.current_shift;
function toast(message,error=false){$('#toast').textContent=message;$('#toast').className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').className='',4500);}
async function api(path,body){
 let res;try{res=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});}catch{throw Error('Sem ligação ao servidor. Verifique a ligação e tente novamente.');}
 const raw=await res.text();let result;
 try{result=JSON.parse(raw);}catch{throw Error(`O servidor devolveu uma resposta incompleta (HTTP ${res.status}). Verifique se o servidor continua ativo e se a porta 3000 está aberta; os dados do formulário foram mantidos.`);}
 if(!res.ok){if(res.status===401&&state){state=null;boot();}throw Error(result.error||`Não foi possível concluir o pedido (HTTP ${res.status}).`);}return result;
}
const num=v=>typeof v==='number'?v:Number(String(v||'0').replace(/[\s\u00a0\u202f]/g,'').replace(',','.'));
function numericDisplay(value,decimals=3){const raw=String(value??'').replace(/[\s\u00a0\u202f]/g,'').replace('.',',').replace(/[^0-9,]/g,'');const [whole='',...fractions]=raw.split(',');const integer=whole.replace(/^0+(?=\d)/,'').replace(/\B(?=(\d{3})+(?!\d))/g,' ');return integer+(fractions.length?', '+fractions.join('').slice(0,decimals):'').replace(', ',',');}
function field(label,name,type='text',value='',extra=''){
 const password=type==='password',numeric=type==='number';if(type==='tel')extra+=' data-phone';if(type==='text'&&name==='barcode')extra+=' maxlength="80"';
 if(numeric){const decimals=extra.includes('step="0.01"')?2:extra.includes('step="0.001"')?3:0;extra=extra.replace(/\bmin=/g,'data-min=').replace(/\bmax=/g,'data-max=').replace(/step="[^"]*"/g,'');extra+=` data-number data-decimals="${decimals}" inputmode="decimal"`;type='text';value=numericDisplay(value,decimals);}
 if(password && name==='password' && !extra.includes('current-password'))extra+=' data-strong-password';
 return `<div class="field"><label for="${name}">${label}</label><div class="${password?'password-wrap':'input-wrap'}"><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>${password?`<button class="eye-button" type="button" data-eye="${name}" aria-label="Mostrar palavra-passe" aria-pressed="false">${icon('eye')}</button>`:''}</div></div>`;
}
function select(label,name,options,value=''){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${options.map(([v,l])=>`<option value="${v}" ${v===value?'selected':''}>${l}</option>`).join('')}</select></div>`;}
function formData(form){const d=Object.fromEntries(new FormData(form));for(const input of form.querySelectorAll('[data-number]'))if(input.name)d[input.name]=String(num(input.value));return d;}
function showModal(title,body){modal.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="ghost" data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="modal-body">${body}</div>`;modal.showModal();}
function formError(form,e){let el=form.querySelector('.form-error');if(!el){el=document.createElement('div');el.className='form-error';form.prepend(el);}el.textContent=e.message;}
async function refresh(){state=await api('state');render();}
async function boot(){try{const setup=await api('setup');if(setup.required)return auth(true);try{state=await api('state');render();}catch{auth(false);}}catch(e){app.innerHTML=`<div class="loading"><h1>Não foi possível ligar à TT LEBILA</h1><p>${esc(e.message)}</p><button data-action="retry">Tentar novamente</button></div>`;}}
function registrationFields(){return `${field('Nome completo','name','text','','required autocomplete="name" data-person-name maxlength="150"')}${field('Bilhete de identidade','bi','text','','required data-bi pattern="[0-9]{9}[A-Za-z]{2}[0-9]{3}" placeholder="009763932CA042" maxlength="14"')}<small class="input-hint">9 algarismos + 2 letras + 3 algarismos. Ex.: 009763932CA042.</small>${field('Data de nascimento','birth_date','date','','required min="1900-01-01" max="'+new Date().toISOString().slice(0,10)+'"')}${field('Telefone','phone','tel','','required autocomplete="tel" data-phone maxlength="20" placeholder="+244 923 456 789"')}${field('Email','email','email','','required autocomplete="email" maxlength="254"')}`;}
function credentials(result){showModal('Conta criada · guarde a palavra-passe',`<p>A palavra-passe foi gerada pelo sistema e só será mostrada agora. Entregue-a em privado ao titular da conta.</p><div class="credential"><label>Email</label><div>${esc(result.email)}</div><label>Palavra-passe inicial</label><div class="generated-secret"><code id="generated-password" data-secret="${esc(result.password)}">${esc(result.password)}</code><button type="button" class="eye-button" data-secret-toggle aria-label="Ocultar palavra-passe">${icon('eye')}</button></div></div><p>Pode iniciar sessão com email ou BI e depois alterar a palavra-passe em <strong>A minha conta</strong>.</p><div class="modal-actions"><button data-action="close">Já guardei a palavra-passe</button></div>`);}
function auth(setup){clearInterval(recoveryTimer);app.innerHTML=`<div class="auth"><section class="auth-hero"><div class="brand"><div class="brand-mark"><span class="tt-symbol">TT</span></div><div class="brand-name">LEBILA<small>COMÉRCIO & GESTÃO</small></div></div><div><div class="eyebrow">MENOS COMPLICAÇÃO. MAIS CONTROLO.</div><h1>O próximo nível<br>do seu <em>negócio.</em></h1><p>Uma visão clara. Uma equipa conectada. O poder de transformar cada atendimento numa nova oportunidade.</p></div><div class="auth-features"><span>01 <b>Stock sob controlo</b></span><span>02 <b>Vendas com confiança</b></span><span>03 <b>Decisões com dados</b></span></div><small>TT LEBILA · Cada dia, mais longe.</small></section><section class="auth-form"><form id="auth-form"><div class="eyebrow">${setup?'CONFIGURAÇÃO INICIAL':'ACESSO RESERVADO À EQUIPA'}</div><h1>${setup?'Cadastrar o proprietário':'Entrar na sua loja'}</h1><p>${setup?'Esta configuração só acontece uma vez. Os próximos cadastros serão feitos pelo gerente ou proprietário. Nome, BI e nascimento não poderão ser alterados.':'Use o seu email ou bilhete de identidade e a sua palavra-passe. Para obter uma conta, contacte o gerente ou proprietário.'}</p>${setup?registrationFields():field('Email ou bilhete de identidade','identifier','text','','required autocomplete="username"')+field('Palavra-passe','password','password','','required autocomplete="current-password"')}<button type="submit">${setup?'Criar conta do proprietário':'Iniciar sessão'} ${icon('arrow')}</button>${!setup?'<button class="forgot-button" type="button" data-action="forgot">Esqueci a palavra-passe</button>':''}<div class="auth-foot">TT LEBILA · O seu negócio, em movimento.</div></form></section></div>`;
 $('#auth-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button:not([type="button"])');b.disabled=true;try{const d=formData(f);if(setup){const result=await api('setup',d);auth(false);credentials(result);}else{await api('login',d);await refresh();}}catch(err){formError(f,err);}finally{b.disabled=false;}};
}
const navs=[['dashboard','grid','Visão geral'],['sales','bag','Ponto de venda'],['products','box','Produtos e stock'],['cash','cash','Caixa'],['history','receipt','Histórico de vendas'],['activity','clock','Atividades'],['users','users','Equipa e permissões'],['account','users','A minha conta']];
function render(){if(!state)return;if(state.recovery_required)return resetScreen();const currentForm=$('#sale-form');if(currentForm)saleDraft=formData(currentForm);const title=navs.find(n=>n[0]===page)?.[2]||'Visão geral';app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark"><span class="tt-symbol">TT</span></div><div class="brand-name">LEBILA<small>GESTÃO DA SUA LOJA</small></div></div><div class="nav-label">ESPAÇO DE TRABALHO</div><nav class="nav">${navs.filter(n=>manager()||!['activity','users'].includes(n[0])).map(([id,i,l])=>`<button data-page="${id}" class="${page===id?'active':''}">${icon(i)}${l}</button>`).join('')}</nav><div class="side-bottom"><div class="side-note">${icon('leaf')}<strong>Crescer começa por cuidar.</strong>Cada produto contado é uma decisão mais segura.</div><div class="user"><div class="avatar">${esc(state.user.name.slice(0,2).toUpperCase())}</div><div><strong>${esc(state.user.name)}</strong><small>${roleLabel[state.user.role]}</small></div><button class="ghost" data-action="logout" title="Terminar sessão">${icon('out')}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">A minha loja <span style="margin:0 12px;color:#ccd3c6">/</span> <b>${title}</b></div><div class="top-right"><span class="date">${new Date().toLocaleDateString('pt-AO',{day:'numeric',month:'long',year:'numeric',timeZone:'Africa/Luanda'})}</span><span><i class="status-dot"></i>Loja conectada</span><button class="ghost" data-action="alerts" title="Alertas de stock">${icon('bell')}</button><button class="ghost mobile-brand" data-action="logout" title="Sair">${icon('out')}</button></div></header><main>${({dashboard:dashboard,sales:pos,products:products,cash:cash,history:history,activity:activity,users:users,account:account}[page]||dashboard)()}<footer class="footer"><span>TT LEBILA · Um negócio mais organizado, todos os dias.</span><span>Valores em Kz · Horários de Angola</span></footer></main></div></div>`;bindPage();installFilters();}
function heading(eyebrow,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;}
function metric(label,value,foot,i){return `<div class="metric"><div class="metric-icon">${icon(i)}</div><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`;}
function empty(message,i='box'){return `<div class="empty">${icon(i)}${message}</div>`;}
function dashboard(){const m=state.metrics,low=state.products.filter(p=>p.stock<=p.minimum),growth=m.previous_week?Math.round((m.current_week/m.previous_week-1)*100):null;const trend=growth===null?'A recolher dados':growth>0?'Vendas em crescimento':growth<0?'Vendas a desacelerar':'Vendas estáveis';return dashboardHero()+heading('PAINEL DE CONTROLO','Visão geral','Os números de hoje. As oportunidades de amanhã.',`<button class="secondary" data-page="history">${icon('receipt')}Ver vendas</button><button data-page="sales">${icon('plus')}Nova venda</button>`)+`<div class="metrics">${metric('Vendas de hoje',money(m.today),`<span class="good">${m.count} ${m.count===1?'venda realizada':'vendas realizadas'}</span>`,'chart')}${metric('Ticket médio',money(m.count?Math.round(m.today/m.count):0),'Valor médio por venda hoje','bag')}${metric('Produtos em catálogo',qty(state.products.length),'Categorias que crescem consigo','box')}${metric('Atenção ao stock',`${low.length} <small>produtos</small>`,`<span class="${low.length?'warn':'good'}">${low.length?'Abaixo ou no limite mínimo':'Tudo dentro dos níveis definidos'}</span>`,'bell')}</div><div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2>O ritmo das suas vendas</h2><p>Receita diária nos últimos 14 dias</p></div><span class="tag ${growth!==null&&growth<0?'amber':''}">${trend}</span></div><div class="chart-summary"><b>${money(m.current_week)}</b><span>${growth===null?'Sem período anterior para comparar':`${growth>0?'+':''}${growth}% face aos 7 dias anteriores`}<br>Últimos 7 dias</span></div><div class="chart-wrap">${chart()}</div><div class="chart-note">${icon('trend')} ${growth===null?'As tendências aparecem quando houver vendas nos dois períodos.':'Comparação entre períodos de 7 dias; não representa lucro.'}</div></section><section class="card"><div class="card-head"><div><h2>Hora de repor</h2><p>Uma prateleira cheia faz a diferença.</p></div><span class="tag amber">${low.length} alertas</span></div><div class="stock-list">${low.slice(0,4).map(p=>`<div class="stock-row"><div class="product-tile">${icon('box')}</div><div><strong>${esc(p.name)}</strong><small>Mínimo: ${qty(p.minimum)} ${esc(p.unit)}</small></div><div class="quantity"><strong>${qty(p.stock)} ${esc(p.unit)}</strong><div class="mini-progress"><i style="width:${Math.min(100,p.minimum?p.stock/p.minimum*100:0)}%"></i></div></div></div>`).join('')||empty('Stock tranquilo por aqui.<br>Os alertas de reposição aparecerão nesta área.','check')}</div><div class="card-foot"><button class="link-btn" data-action="alerts">Consultar stock ${icon('arrow')}</button></div></section></div><section class="card"><div class="card-head table-title"><div><h2>Últimas vendas</h2><p>Um registo de cada atendimento.</p></div><button class="link-btn" data-page="history">Ver todas ${icon('arrow')}</button></div>${salesTable(state.sales.slice(0,5))}</section>`;}
function chart(){
 const mobile=window.innerWidth<480,width=mobile?340:620,left=mobile?47:48,right=width-20,bottom=180;
 const days=Array.from({length:14},(_,i)=>{const d=new Date(Date.now()+3600000);d.setUTCDate(d.getUTCDate()-13+i);return d.toISOString().slice(0,10);});
 const values=days.map(d=>state.chart.find(c=>c.day===d)?.total||0),max=Math.max(...values,10000),x=i=>left+i*((right-left)/13),y=v=>bottom-v/max*140;
 const points=values.map((v,i)=>`${x(i)},${y(v)}`).join(' ');
 return `<svg class="chart" viewBox="0 0 ${width} 220" role="img" aria-label="Receita diária em Kz nos últimos 14 dias"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#3898ff" stop-opacity=".23"/><stop offset="100%" stop-color="#3898ff" stop-opacity=".01"/></linearGradient></defs>${[0,.25,.5,.75,1].map(v=>`<line x1="${left}" y1="${y(v*max)}" x2="${right}" y2="${y(v*max)}" stroke="#e5edf8" stroke-dasharray="4 5"/><text x="${left-10}" y="${y(v*max)+3}" text-anchor="end">${new Intl.NumberFormat('pt',{notation:'compact'}).format(max*v/100)}</text>`).join('')}<polygon points="${left},180 ${points} ${right},180" fill="url(#area)"/><polyline points="${points}" fill="none" stroke="#237cf0" stroke-width="2.5" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3" fill="#237cf0"><title>${days[i]}: ${money(v)}</title></circle>`).join('')}${days.map((d,i)=>i%(mobile?4:2)===0||i===13?`<text x="${x(i)}" y="207" text-anchor="middle">${d.slice(8)}/${d.slice(5,7)}</text>`:'').join('')}</svg>`;
}
function salesTable(sales){return !sales.length?empty('Ainda não há vendas.<br>Abra o caixa e registe o primeiro atendimento.','receipt'):`<div class="table-wrap"><table><thead><tr><th>RECIBO</th><th>CLIENTE / DATA</th><th>VENDEDOR</th><th>PAGAMENTO</th><th>TOTAL</th><th></th></tr></thead><tbody>${sales.map(s=>`<tr><td><strong>#${String(s.id).padStart(5,'0')}</strong></td><td><strong>${esc(s.customer)}</strong><span class="sub">${date(s.created)}</span></td><td>${esc(s.seller)}</td><td><span class="tag gray">${methodLabel[s.method]}</span></td><td><strong>${money(s.total)}</strong></td><td><button class="ghost small" data-receipt="${s.id}">${icon('receipt')}Ver</button></td></tr>`).join('')}</tbody></table></div>`;}
function products(){const list=state.products.filter(p=>(!stockOnly||p.stock<=p.minimum)&&(!category||p.category===category)&&`${p.name} ${p.barcode||''}`.toLowerCase().includes(search.toLowerCase()));return heading('CADA PRODUTO NO SEU LUGAR','Produtos e stock','Embalagens na entrada. Unidades, peso ou volume na venda.',manager()?`<button data-action="new-product">${icon('plus')}Adicionar produto</button>`:'')+`<div class="toolbar"><div class="search">${icon('search')}<input id="product-search" placeholder="Pesquisar produto ou código de barras…" value="${esc(search)}" aria-label="Pesquisar produtos"></div><select id="category-filter" aria-label="Categoria"><option value="">Todas as categorias</option>${[...new Set(state.products.map(p=>p.category))].map(c=>`<option ${c===category?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="${stockOnly?'':'secondary'}" data-action="toggle-low">${icon('bell')}Stock baixo</button></div><section class="card">${list.length?`<div class="table-wrap"><table><thead><tr><th>PRODUTO</th><th>CATEGORIA</th><th>STOCK DISPONÍVEL</th><th>EMBALAGEM</th>${manager()?'<th>CUSTO / EMBALAGEM</th>':''}<th>PREÇO / UNIDADE</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><strong>${esc(p.name)}</strong><span class="sub">${esc(p.barcode||'Sem código de barras')}</span></td><td>${esc(p.category)}</td><td><span class="tag ${p.stock<=p.minimum?'amber':''}">${qty(p.stock)} ${esc(p.unit)}</span><span class="sub">Mínimo: ${qty(p.minimum)} ${esc(p.unit)}</span></td><td>${esc(p.pack_type)} · ${qty(p.pack_size)} ${esc(p.unit)}<span class="sub">Equivale a ${qty(p.stock/p.pack_size)} embalagens</span></td>${manager()?`<td>${money(p.pack_cost)}</td>`:''}<td><strong>${money(p.price)}</strong> / ${esc(p.unit)}</td><td>${manager()?`<button class="secondary small" data-stock="${p.id}">${icon('plus')}Entrada</button> <button class="ghost small" data-product="${p.id}">Editar</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum produto encontrado.<br>Adicione os seus produtos para começar.')}</section>`+(manager()?purchases():'');}
function productModal(id){const p=state.products.find(p=>p.id===id)||{name:'',category:'Alimentares',unit:'un',pack_type:'Caixa',pack_size:12,pack_cost:0,price:0,minimum:5};showModal(id?'Editar produto':'Um novo produto na prateleira',`<form id="product-form"><div class="form-grid"><div class="full">${field('Nome do produto','name','text',p.name,'required maxlength="150"')}</div>${field('Categoria (pode criar uma nova)','category','text',p.category,'required list="categories"')}<datalist id="categories">${[...new Set(['Alimentares','Higiene','Bebidas',...state.products.map(p=>p.category)])].map(c=>`<option value="${esc(c)}">`).join('')}</datalist>${select('Unidade de venda','unit',[['un','Unidade'],['kg','Quilograma (kg)'],['L','Litro (L)'],['g','Grama (g)'],['mL','Mililitro (mL)']],p.unit)}${field('Código de barras (opcional)','barcode','text',p.barcode||'','maxlength="80"')}${field('Alerta de stock mínimo','minimum','number',p.minimum,'required min="0" step="0.001"')}${field('Tipo de embalagem','pack_type','text',p.pack_type,'required placeholder="Caixa, pacote, saco…"')}${field('Conteúdo por embalagem (na unidade de venda)','pack_size','number',p.pack_size,'required min="0.001" step="0.001"')}${field('Custo de aquisição por embalagem (Kz)','pack_cost','number',p.pack_cost/100,'required min="0" step="0.01"')}${field('Preço de venda por unidade (Kz)','price','number',p.price/100,'required min="0" step="0.01"')}</div><p class="help">Exemplo: um saco com 25 kg → unidade kg, conteúdo 25. Registe a entrada de stock depois de guardar.</p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Guardar produto</button></div></form>`);$('#product-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,d=formData(form);for(const k of ['minimum','pack_size','pack_cost','price'])d[k]=Number(d[k]);if(id)d.id=id;await submit(form,()=>api('products',d),'Produto guardado.');};}
function stockModal(id){const p=state.products.find(p=>p.id===id);showModal('Receber mercadoria',`<form id="stock-form"><h2>${esc(p.name)}</h2><p>1 ${esc(p.pack_type)} = ${qty(p.pack_size)} ${esc(p.unit)} · Custo: ${money(p.pack_cost)}</p>${field('Quantidade de embalagens recebidas','packs','number',1,'required min="0.001" step="0.001"')}${field('Referência / fornecedor / motivo','reason','text','','required placeholder="Ex.: Compra ao fornecedor, documento nº…"')}<p class="help">O stock é convertido automaticamente para a unidade de venda. A entrada não é retirada do caixa de vendas.</p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Confirmar entrada</button></div></form>`);$('#stock-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f);await submit(f,()=>api('stock',{...d,packs:Number(d.packs),product_id:id}),'Stock atualizado.');};}
function pos(){const open=shift();const list=state.products.filter(p=>(!category||p.category===category)&&`${p.name} ${p.barcode||''}`.toLowerCase().includes(search.toLowerCase()));return heading('UM BOM ATENDIMENTO COMEÇA AQUI','Ponto de venda','Selecione os produtos ou leia o código de barras.',`<span class="tag ${open?'':'amber'}">${open?'Caixa #'+open.id+' aberto':'Caixa fechado'}</span>`)+(!open?`<div class="banner"><span>Abra o seu caixa para poder finalizar vendas.</span><button class="small" data-action="open-shift">Abrir caixa</button></div>`:'')+`<div class="pos-grid"><section><div class="toolbar"><div class="search">${icon('search')}<input id="pos-search" aria-label="Pesquisar ou ler código" placeholder="Produto ou código de barras + Enter" value="${esc(search)}" autocomplete="off"></div><select id="pos-category" aria-label="Categoria no ponto de venda"><option value="">Todas as categorias</option>${[...new Set(state.products.map(p=>p.category))].map(c=>`<option ${c===category?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="secondary" data-action="barcode" title="Leitor USB ou Bluetooth">${icon('barcode')}Leitor</button></div><div class="product-grid">${list.map(p=>`<button class="product-button" data-add="${p.id}"><div class="product-tile">${icon(p.category==='Higiene'?'leaf':'box')}</div><strong>${esc(p.name)}</strong><span>${qty(p.stock)} ${esc(p.unit)} disponíveis</span><b>${money(p.price)} <small>/ ${esc(p.unit)}</small></b></button>`).join('')}</div>${!list.length?empty('Nenhum produto encontrado.'):''}</section><section class="card"><div class="card-head"><div><h2>Venda atual</h2><p>${cart.length} produtos no atendimento</p></div><button class="ghost small" data-action="clear-cart" title="Limpar venda">${icon('close')}</button></div><div class="cart-body"><div id="cart-lines">${cart.length?cart.map(i=>{const p=state.products.find(p=>p.id===i.product_id);return `<div class="cart-item"><div><strong>${esc(p.name)}</strong><small>${money(p.price)} / ${esc(p.unit)}</small></div><input type="text" inputmode="decimal" data-number data-decimals="3" aria-label="Quantidade de ${esc(p.name)}" data-quantity="${p.id}" value="${numericDisplay(i.quantity)}" data-min="${p.unit==='un'?1:0.001}" step="${p.unit==='un'?1:0.001}"><button class="ghost small" data-remove="${p.id}" title="Remover">×</button></div>`;}).join(''):empty('O próximo atendimento<br>começa com um produto.','bag')}</div><form id="sale-form">${field('Cliente (opcional)','customer','text',saleDraft.customer,'placeholder="Consumidor final"')}<div class="form-grid">${field('Desconto total (Kz)','discount','number',saleDraft.discount,'required min="0" step="0.01"')}${select('Pagamento','method',Object.entries(methodLabel),saleDraft.method)}</div><div class="totals"><span>Subtotal</span><b id="subtotal"></b></div><div class="totals final"><span>Total</span><span id="sale-total"></span></div>${field('Valor entregue pelo cliente (Kz)','paid','number',saleDraft.paid,'required min="0" step="0.01"')}<div class="totals"><span>Troco a entregar</span><b id="sale-change"></b></div><button class="checkout" ${!open||!cart.length?'disabled':''}>${icon('check')}Finalizar e emitir recibo</button><p class="help">Stock e preços confirmados ao finalizar. Em TPA / transferência, receba o valor exato.</p></form></div></section></div>`;}
function updateTotals(){const subtotal=cart.reduce((s,i)=>s+Math.round((state.products.find(p=>p.id===i.product_id)?.price||0)*i.quantity),0),discount=num($('#discount')?.value||0)*100,total=Math.max(0,Math.round(subtotal)-discount);$('#subtotal').textContent=money(Math.round(subtotal));$('#sale-total').textContent=money(total);$('#sale-change').textContent=money(Math.max(0,num($('#paid').value||0)*100-total));}
function cash(){const s=shift(),sales=s?state.sales.filter(v=>v.shift_id===s.id):[],cashTotal=s?.cash_sales||0;return heading('CONTAS CERTAS, DIA TRANQUILO','Gestão de caixa','Cada vendedor tem o seu caixa. Vendas eletrónicas são registadas à parte.',s?`<button class="secondary" data-action="close-shift">Fechar o meu caixa</button>`:`<button data-action="open-shift">${icon('plus')}Abrir o meu caixa</button>`)+`<div class="stack"><section class="card shift-card"><h2>${s?'O seu caixa está aberto':'O seu caixa está fechado'}</h2><p>${s?'Aberto em '+date(s.opened):'Defina o fundo inicial antes do primeiro atendimento.'}</p>${s?`<div class="shift-values"><div><small>Fundo inicial</small><b>${money(s.opening)}</b></div><div><small>Vendas em dinheiro</small><b>${money(cashTotal)}</b></div><div><small>Esperado em caixa</small><b>${money(s.opening+cashTotal)}</b></div></div><p class="help">O esperado inclui o fundo inicial e todas as vendas em dinheiro deste caixa, já descontados os trocos.</p>`:''}</section><section class="card"><div class="card-head table-title"><h2>Histórico de caixas</h2><span class="tag gray">Últimos 50</span></div>${state.shifts.length?`<div class="table-wrap"><table><thead><tr><th>CAIXA / VENDEDOR</th><th>ABERTURA</th><th>FECHO</th><th>FUNDO</th><th>ESPERADO</th><th>CONTADO</th><th>DIFERENÇA</th></tr></thead><tbody>${state.shifts.map(s=>`<tr><td><strong>#${s.id} · ${esc(s.seller)}</strong></td><td>${date(s.opened)}</td><td>${s.closed?date(s.closed):'<span class="tag">Aberto</span>'}</td><td>${money(s.opening)}</td><td>${s.closed?money(s.expected):'—'}</td><td>${s.closed?money(s.closing):'—'}</td><td>${s.closed?`<span class="tag ${s.closing!==s.expected?'amber':''}">${money(s.closing-s.expected)}</span>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('Os movimentos de caixa aparecerão aqui.','cash')}</section></div>`;}
function shiftModal(close=false){showModal(close?'Fechar e conferir o caixa':'Começar um novo caixa',`<form id="shift-form"><p>${close?'Conte o dinheiro físico, incluindo o fundo inicial. O sistema irá registar a diferença em relação ao esperado.':'Indique o dinheiro disponível para trocos no início do turno.'}</p>${field(close?'Dinheiro contado (Kz)':'Fundo inicial (Kz)',close?'closing':'opening','number','','required min="0" step="0.01"')}<div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>${close?'Confirmar fecho':'Abrir caixa'}</button></div></form>`);$('#shift-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f);const key=close?'closing':'opening';await submit(f,()=>api('shifts/'+(close?'close':'open'),{[key]:Number(d[key])}),close?'Caixa fechado. Consulte a diferença no histórico.':'Caixa aberto. Boas vendas!');};}
function history(){return heading('CADA VENDA TEM UMA HISTÓRIA','Histórico de vendas','Consulte os últimos 100 recibos, com produtos, descontos e trocos.',`<button class="secondary" data-action="export">${icon('receipt')}Exportar CSV</button>`)+`<div class="toolbar"><div class="search">${icon('search')}<input id="history-search" placeholder="Pesquisar recibo, cliente ou vendedor…" aria-label="Pesquisar vendas"></div></div><section class="card" id="history-table">${salesTable(state.sales)}</section>`;}
function activity(){return heading('TRANSPARÊNCIA EM CADA PASSO','Histórico de atividades','Últimos 100 registos: quem fez, o que fez e quando.')+`<section class="card">${state.audit.length?`<div class="table-wrap"><table><thead><tr><th>ATIVIDADE</th><th>DETALHES</th><th>RESPONSÁVEL</th><th>DATA E HORA</th></tr></thead><tbody>${state.audit.map(a=>`<tr><td><span class="audit-type"></span><strong>${esc(a.action)}</strong></td><td>${esc(a.detail)}</td><td>${esc(a.actor)}</td><td>${date(a.created)}</td></tr>`).join('')}</tbody></table></div>`:empty('As ações da sua equipa ficarão registadas aqui.','clock')}</section>`;}
function users(){return heading('PESSOAS QUE FAZEM A TT LEBILA','Equipa e permissões','Um proprietário. Um gerente. Uma equipa de vendedores.',`<button data-action="new-user">${icon('plus')}Adicionar pessoa</button>${state.user.role==='proprietario'?'<button class="secondary" data-action="transfer">Transferir propriedade</button>':''}`)+`<div class="team-summary"><span>${icon('users')} ${state.users.length} pessoas na equipa</span><span>Proprietário: ${esc(state.users.find(u=>u.role==='proprietario')?.name||'—')}</span><span>Gerente: ${esc(state.users.find(u=>u.role==='gerente')?.name||'Por definir')}</span></div><section class="card"><div class="table-wrap"><table><thead><tr><th>NOME / BI</th><th>NASCIMENTO</th><th>CONTACTOS</th><th>PERFIL</th><th>ESTADO</th><th>GESTÃO</th></tr></thead><tbody>${state.users.map(u=>`<tr><td><strong>${esc(u.name)}</strong><span class="sub">${esc(u.bi||'Por completar')}</span></td><td>${esc(u.birth_date||'—')}</td><td>${esc(u.email||'—')}<span class="sub">${esc(u.phone||'—')}</span></td><td><span class="tag ${u.role==='proprietario'?'blue':''}">${roleLabel[u.role]}</span></td><td><span class="tag ${u.active?'':'gray'}">${u.active?'Ativo':'Inativo'}</span></td><td>${(state.user.role==='proprietario'||u.role==='vendedor'||u.id===state.user.id)?`<button class="secondary small" data-contact="${u.id}">Contactos</button>`:''} ${u.id!==state.user.id&&u.role!=='proprietario'&&(state.user.role==='proprietario'||u.role==='vendedor')?`<div class="row-actions"><button class="secondary small" data-access="${u.id}">Acesso</button><button class="ghost small" data-reset="${u.id}">Repor senha</button><button class="danger small" data-remove-user="${u.id}">Remover</button></div>`:''}</td></tr>`).join('')}</tbody></table></div></section>`;}
function userModal(){showModal('Cadastrar uma pessoa',`<form id="user-form">${registrationFields()}${select('Perfil de acesso','role',state.user.role==='proprietario'&&!state.users.some(u=>u.role==='gerente')?[['vendedor','Vendedor'],['gerente','Gerente']]:[['vendedor','Vendedor']],'vendedor')}<p class="help">Confira os dados: nome, BI e nascimento não poderão ser alterados. Será gerada uma palavra-passe única.</p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Criar utilizador</button></div></form>`);$('#user-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button:not([type="button"])');b.disabled=true;try{const r=await api('users',formData(f));modal.close();await refresh();credentials(r);}catch(err){formError(f,err);}finally{b.disabled=false;}};}
function accessModal(id){const u=state.users.find(u=>u.id===id);showModal('Permissões de '+esc(u.name),`<form id="access-form">${select('Perfil','role',state.user.role==='proprietario'&&(!state.users.some(x=>x.role==='gerente')||u.role==='gerente')?[['vendedor','Vendedor'],['gerente','Gerente']]:[['vendedor','Vendedor']],u.role)}${select('Estado da conta','active',[['true','Ativo'],['false','Inativo']],String(!!u.active))}<p class="help">As sessões desta pessoa serão terminadas ao guardar.</p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Guardar permissões</button></div></form>`);$('#access-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f);await submit(f,()=>api('users/access',{id,role:d.role,active:d.active==='true'}),'Permissões atualizadas.');};}
function contactModal(id){const u=state.users.find(u=>u.id===id);showModal('Contactos de '+esc(u.name),`<form id="contact-form">${field('Email','email','email',u.email,'required')}${field('Telefone','phone','tel',u.phone,'required')}<p class="help">O email atualizado passa a ser usado no login. O BI mantém-se válido.</p><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Guardar contactos</button></div></form>`);$('#contact-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;await submit(f,()=>api('users/profile',{id,...formData(f)}),'Contactos atualizados.');};}
function account(){const u=state.user;return heading('OS SEUS DADOS E A SUA SEGURANÇA','A minha conta','Pode alterar os contactos e a palavra-passe. Os dados de identidade são permanentes.')+`<div class="dashboard-grid"><section class="card shift-card"><h2>Identificação</h2><p>Nome: <strong>${esc(u.name)}</strong><br>BI: <strong>${esc(u.bi)}</strong><br>Nascimento: <strong>${esc(u.birth_date)}</strong></p><hr><form id="profile-form">${field('Email','email','email',u.email,'required')}${field('Telefone','phone','tel',u.phone,'required')}<button>Guardar contactos</button></form></section><section class="card shift-card"><h2>Alterar palavra-passe</h2><p>Pelo menos 8 caracteres, com letras, números e um carácter especial.</p><form id="password-form">${field('Palavra-passe atual','current_password','password','','required autocomplete="current-password"')}${field('Nova palavra-passe','password','password','','required minlength="8" autocomplete="new-password"')}${field('Confirmar nova palavra-passe','confirmation','password','','required minlength="8" autocomplete="new-password"')}<button>Alterar palavra-passe</button></form></section></div>`;}
function purchases(){return `<section class="card" style="margin-top:24px"><div class="card-head table-title"><div><h2>Compras e entradas de stock</h2><p>Últimos 100 registos · data e hora de Angola</p></div></div>${state.purchases.length?`<div class="table-wrap"><table><thead><tr><th>DATA E HORA</th><th>PRODUTO</th><th>QUANTIDADE</th><th>CUSTO</th><th>RESPONSÁVEL</th><th>REFERÊNCIA</th></tr></thead><tbody>${state.purchases.map(m=>`<tr><td>${date(m.created)}</td><td><strong>${esc(m.product)}</strong></td><td>${qty(m.quantity)} ${esc(m.unit)}</td><td>${money(m.cost)}</td><td>${esc(m.actor)}</td><td>${esc(m.reason)}</td></tr>`).join('')}</tbody></table></div>`:empty('As entradas de mercadoria serão registadas com data, hora e responsável.','clock')}</section>`;}
async function showReceipt(id){try{const r=await api('sales/'+id);showModal('Recibo da venda',`<div class="receipt"><div class="receipt-title"><h2>TT LEBILA</h2><div>COMPROVATIVO INTERNO DE VENDA</div><strong>N.º ${String(r.id).padStart(5,'0')}</strong></div><div>Data: ${date(r.created)}</div><div>Vendedor: ${esc(r.seller)}</div><div>Cliente: ${esc(r.customer)}</div><div>Caixa: #${r.shift_id}</div><table><thead><tr><th>Produto</th><th>Qtd.</th><th>Preço</th><th>Total</th></tr></thead><tbody>${r.items.map(i=>`<tr><td>${esc(i.name)}</td><td>${qty(i.quantity)} ${esc(i.unit)}</td><td>${money(i.price)}</td><td>${money(i.total)}</td></tr>`).join('')}</tbody></table><div class="totals"><span>Subtotal</span><span>${money(r.subtotal)}</span></div><div class="totals"><span>Desconto</span><span>− ${money(r.discount)}</span></div><div class="totals final"><span>Total pago pela compra</span><span>${money(r.total)}</span></div><div class="totals"><span>Valor entregue</span><span>${money(r.paid)}</span></div><div class="totals"><span>Troco entregue</span><span>${money(r.change_due)}</span></div><div>Pagamento: ${methodLabel[r.method]}</div><div class="disclaimer">Obrigado pela sua preferência!<br>Documento interno sem validade fiscal.<br>Não substitui uma fatura emitida por software certificado.</div></div><div class="modal-actions"><button class="secondary" data-action="close">Fechar</button><button data-action="print">${icon('print')}Imprimir</button></div>`);}catch(e){toast(e.message,true);}}
async function submit(form,fn,message){const b=form.querySelector('button:not([type="button"])');if(b)b.disabled=true;try{await fn();modal.close();await refresh();toast(message);}catch(e){formError(form,e);}finally{if(b)b.disabled=false;}}
function bindPage(){if(page==='account'){
 $('#profile-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;await submit(f,()=>api('profile',formData(f)),'Contactos atualizados.');};
 $('#password-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f);if(d.password!==d.confirmation)return formError(f,Error('As palavras-passe não coincidem.'));await submit(f,()=>api('password',d),'Palavra-passe alterada. Outras sessões foram terminadas.');};
 }
if(page==='products'){$('#product-search').oninput=e=>{const pos=e.target.selectionStart;search=e.target.value;render();$('#product-search').focus();$('#product-search').setSelectionRange(pos,pos);};$('#category-filter').onchange=e=>{category=e.target.value;render();};}
  if(page==='sales'){$('#pos-category').onchange=e=>{category=e.target.value;render();};$('#pos-search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;render();$('#pos-search').focus();$('#pos-search').setSelectionRange(pos,pos);};$('#pos-search').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();const p=state.products.find(p=>p.barcode===e.target.value.trim());if(p){addCart(p.id);search='';render();$('#pos-search').focus();}else toast('Código não encontrado. Registe-o no produto.',true);}};updateTotals();for(const id of ['discount','paid'])$('#'+id).oninput=updateTotals;$('#method').onchange=()=>{if($('#method').value!=='dinheiro'){const sub=cart.reduce((s,i)=>s+Math.round(state.products.find(p=>p.id===i.product_id).price*i.quantity),0);$('#paid').value=Math.max(0,sub/100-num($('#discount').value));}updateTotals();};$('#sale-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f),b=f.querySelector('button:not([type="button"])');b.disabled=true;try{const receipt=await api('sales',{...d,discount:Number(d.discount),paid:Number(d.paid),items:cart});cart=[];saleDraft={customer:'',discount:'0',paid:'',method:'dinheiro'};f.reset();await refresh();await showReceipt(receipt.id);toast('Venda registada. Stock atualizado.');}catch(err){formError(f,err);}finally{b.disabled=false;}};}
  if(page==='history')$('#history-search')?.closest('.toolbar')?.remove();
}
function addCart(id){const p=state.products.find(p=>p.id===id),current=cart.find(i=>i.product_id===id),amount=p.unit==='un'?1:Math.min(1,p.stock);if(p.stock<=0||(current?.quantity||0)+amount>p.stock){toast('Sem stock disponível para essa quantidade.',true);return;}if(current)current.quantity=Math.round((current.quantity+amount)*1000)/1000;else cart.push({product_id:id,quantity:amount});}
document.addEventListener('change',e=>{const id=Number(e.target.dataset.quantity);if(id){const i=cart.find(i=>i.product_id===id),p=state.products.find(p=>p.id===id),v=num(e.target.value);if(v>0&&v<=p.stock&&(p.unit!=='un'||Number.isInteger(v)))i.quantity=v;else toast('Quantidade inválida ou superior ao stock.',true);e.target.value=numericDisplay(i.quantity,3);updateTotals();}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;
  if(b.hasAttribute('data-secret-toggle')){const code=$('#generated-password');const hidden=code.textContent.startsWith('•');code.textContent=hidden?code.dataset.secret:'••••••••••••';b.setAttribute('aria-label',hidden?'Ocultar palavra-passe':'Mostrar palavra-passe');return;}
  if(b.dataset.eye){const input=document.getElementById(b.dataset.eye);const showing=input.type==='password';input.type=showing?'text':'password';b.setAttribute('aria-label',showing?'Ocultar palavra-passe':'Mostrar palavra-passe');b.setAttribute('aria-pressed',String(showing));return;}
  if(b.dataset.removeUser)return removeUserModal(Number(b.dataset.removeUser));
  if(b.dataset.page){page=b.dataset.page;search='';category='';stockOnly=false;filters={};render();window.scrollTo(0,0);return;}
  if(b.dataset.contact)return contactModal(Number(b.dataset.contact));if(b.dataset.reset){const id=Number(b.dataset.reset);showModal('Repor palavra-passe?',`<p>A palavra-passe atual será substituída e as sessões desta pessoa serão terminadas.</p><div class="modal-actions"><button class="secondary" data-action="close">Cancelar</button><button data-confirm-reset="${id}">Gerar nova palavra-passe</button></div>`);return;}if(b.dataset.confirmReset){b.disabled=true;try{const r=await api('users/reset-password',{id:Number(b.dataset.confirmReset)});modal.close();credentials(r);}catch(err){toast(err.message,true);b.disabled=false;}return;}
  if(b.dataset.product)return productModal(Number(b.dataset.product));if(b.dataset.stock)return stockModal(Number(b.dataset.stock));if(b.dataset.receipt)return showReceipt(Number(b.dataset.receipt));if(b.dataset.access)return accessModal(Number(b.dataset.access));
  if(b.dataset.add){addCart(Number(b.dataset.add));render();return;}if(b.dataset.remove){cart=cart.filter(i=>i.product_id!==Number(b.dataset.remove));render();return;}
  const action=b.dataset.action;
  if(action==='forgot')return recoveryScreen();if(action==='login')return auth(false);if(action==='retry')return boot();if(action==='transfer')return transferModal();
  if(action==='close')modal.close();if(action==='new-product')productModal();if(action==='new-user')userModal();if(action==='open-shift')shiftModal();if(action==='close-shift')shiftModal(true);if(action==='print')window.print();
  if(action==='logout'){try{await api('logout',{});state=null;cart=[];saleDraft={customer:'',discount:'0',paid:'',method:'dinheiro'};page='dashboard';auth(false);}catch(err){toast(err.message,true);}}
  if(action==='alerts'){page='products';stockOnly=true;search='';category='';render();}
  if(action==='toggle-low'){stockOnly=!stockOnly;render();}
  if(action==='clear-cart'){if(cart.length)showModal('Limpar a venda atual?',`<p>Os produtos desta venda serão removidos. Nenhuma venda será gravada.</p><div class="modal-actions"><button class="secondary" data-action="close">Voltar</button><button class="danger" data-action="confirm-clear">Limpar venda</button></div>`);}
  if(action==='confirm-clear'){cart=[];saleDraft={customer:'',discount:'0',paid:'',method:'dinheiro'};$('#sale-form')?.reset();modal.close();render();}
  if(action==='barcode'){showModal('Leitura de códigos de barras',`<p>Ligue um leitor USB ou Bluetooth configurado como teclado, com sufixo Enter. Depois, coloque o cursor no campo de pesquisa e leia o código.</p><p>O produto deve ter o código registado no catálogo. A leitura por câmara não está incluída nesta versão.</p><div class="modal-actions"><button data-action="scan-focus">Ativar campo de leitura</button></div>`);}
  if(action==='scan-focus'){modal.close();$('#pos-search').focus();}
  if(action==='export'){const cell=v=>'"'+String(v).replace(/^[=+@\-]/,"'$&").replace(/"/g,'""')+'"';const rows=[['Recibo','Data UTC','Cliente','Vendedor','Pagamento','Subtotal Kz','Desconto Kz','Total Kz','Entregue Kz','Troco Kz'],...state.sales.map(s=>[s.id,s.created,s.customer,s.seller,methodLabel[s.method],s.subtotal/100,s.discount/100,s.total/100,s.paid/100,s.change_due/100])];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='vendas-loja-clara.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
});
modal.addEventListener('close',()=>{if(!modal.open)modal.replaceChildren();});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
function dashboardHero(){const hour=Number(new Intl.DateTimeFormat('en',{hour:'numeric',hour12:false,timeZone:'Africa/Luanda'}).format(new Date()));const greeting=hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite';return `<section class="dashboard-hero"><div class="hero-copy"><div class="hero-kicker"><span></span> O SEU NEGÓCIO, EM MOVIMENTO</div><h1>${greeting}, <span>${esc(state.user.name.split(' ')[0])}.</span><br>Vamos fazer acontecer?</h1><p>Transforme os números de hoje nas conquistas de amanhã.<br>A sua loja, a sua equipa, tudo conectado.</p><button data-page="sales">Iniciar uma venda ${icon('arrow')}</button></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hero-art-card"><div class="art-card-label">TT LEBILA <span>● AO VIVO</span></div><div class="art-total">${money(state.metrics.today)}</div><div class="art-caption">em vendas hoje</div><div class="art-spark">${chart().replaceAll('id="area"','id="hero-area"').replaceAll('url(#area)','url(#hero-area)')}</div><div class="art-card-footer">${icon('trend')} Cada movimento conta.</div></div><div class="art-badge">${icon('check')} Gestão com confiança</div></div></section>`;}
function removeUserModal(id){const u=state.users.find(x=>x.id===id);showModal('Remover '+esc(u.name)+'?',`<p>Esta pessoa deixará de poder entrar. Os seus recibos, caixas e atividades continuarão no histórico. É necessário fechar o caixa antes da remoção.</p><form id="remove-user-form"><div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button class="danger">Confirmar remoção</button></div></form>`);$('#remove-user-form').onsubmit=async e=>{e.preventDefault();await submit(e.currentTarget,()=>api('users/remove',{id}),'Utilizador removido. Histórico preservado.');};}
function transferModal(){const targets=state.users.filter(u=>u.id!==state.user.id&&u.active);if(!targets.length)return toast('Cadastre primeiro a pessoa que vai assumir a propriedade.',true);showModal('Transferir a propriedade',`<form id="transfer-form"><div class="notice">Apenas uma pessoa pode ser proprietária. Ao confirmar, passará a vendedor e as sessões dos dois utilizadores serão terminadas. Esta operação fica registada.</div>${select('Novo proprietário','id',targets.map(u=>[String(u.id),u.name+' · '+roleLabel[u.role]]))}${field('Confirme a sua palavra-passe','password','password','','required autocomplete="current-password"')}<div class="modal-actions"><button type="button" class="secondary" data-action="close">Cancelar</button><button>Confirmar transferência</button></div></form>`);$('#transfer-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button:not([type="button"])');b.disabled=true;try{const d=formData(f);await api('users/transfer-owner',{id:Number(d.id),password:d.password});modal.close();state=null;cart=[];auth(false);toast('Propriedade transferida. Inicie sessão novamente.');}catch(err){formError(f,err);}finally{b.disabled=false;}};}
let recoveryTimer;
function accessLayout(content){app.innerHTML=`<div class="recovery-page"><div class="brand"><div class="brand-mark"><span class="tt-symbol">TT</span></div><div class="brand-name">LEBILA<small>COMÉRCIO & GESTÃO</small></div></div><section class="recovery-card">${content}</section><p class="recovery-footer">TT LEBILA · A confiança faz parte do nosso negócio.</p></div>`;}
async function recoveryScreen(){clearInterval(recoveryTimer);accessLayout(`<div class="eyebrow">VAMOS RECUPERAR O SEU ACESSO</div><h1>Esqueceu a palavra-passe?</h1><p>Enviaremos um código de 6 algarismos para o email ou telefone já associado à sua conta. É válido durante 2 minutos.</p><form id="recover-form">${field('Email ou BI da conta','identifier','text','','required autocomplete="username"')}${select('Como quer receber o código?','channel',[['email','Email'],['sms','SMS no telefone registado']])}<div id="recovery-availability" class="notice">A verificar os canais disponíveis…</div><button type="submit">Enviar código ${icon('arrow')}</button><button type="button" class="forgot-button" data-action="login">Voltar ao login</button></form>`);let options;try{options=await api('recovery/options');}catch(e){$('#recovery-availability').textContent=e.message;return;}if(!$('#recover-form'))return;$('#recovery-availability').textContent=options.email||options.sms?'O destino é sempre o contacto registado. Não é possível indicar outro email ou telefone neste pedido.':'O envio de email e SMS ainda não foi ativado pelo proprietário. Peça-lhe a reposição da sua palavra-passe.';for(const o of $('#channel').options)o.disabled=!options[o.value];if(options.email)$('#channel').value='email';else if(options.sms)$('#channel').value='sms';$('#recover-form button[type="submit"]').disabled=!options.email&&!options.sms;$('#recover-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button[type="submit"]');b.disabled=true;try{const d=formData(f),r=await api('recovery/request',d);codeScreen(r,d);}catch(err){formError(f,err);}finally{b.disabled=false;}};}
function codeScreen(result,request){const deadline=Date.now()+result.expires_in*1000;accessLayout(`<div class="eyebrow">CONFIRME QUE É VOCÊ</div><h1>Introduza o seu código</h1><p>${esc(result.message)}</p><div class="code-countdown" id="countdown" role="timer">02:00</div><form id="code-form">${field('Código temporário','code','text','','required inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" data-code placeholder="000000"')}<button>Entrar com código</button><button type="button" class="forgot-button" data-action="forgot">Pedir outro código</button><button type="button" class="forgot-button" data-action="login">Voltar ao login</button></form>`);clearInterval(recoveryTimer);recoveryTimer=setInterval(()=>{if(!$('#countdown'))return clearInterval(recoveryTimer);const remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('#countdown').textContent=remaining?`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`:'Código expirado · peça outro';if(!remaining){$('#code-form button:not([type="button"])').disabled=true;clearInterval(recoveryTimer);}},1000);$('#code-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button:not([type="button"])');b.disabled=true;try{await api('recovery/verify',{challenge:result.challenge,code:formData(f).code});clearInterval(recoveryTimer);await refresh();}catch(err){formError(f,err);}finally{b.disabled=false;}};}
function resetScreen(){accessLayout(`<div class="eyebrow">ACESSO RECUPERADO</div><h1>Crie uma nova palavra-passe</h1><p>Olá, ${esc(state.user.name)}. A sua senha antiga não pode ser visualizada. Defina uma nova para continuar para a loja.</p><form id="recovered-password-form">${field('Nova palavra-passe','password','password','','required minlength="8" autocomplete="new-password" data-strong-password')}${field('Confirmar palavra-passe','confirmation','password','','required minlength="8" autocomplete="new-password"')}<div class="password-rules">8 ou mais caracteres · letras · números · carácter especial</div><button>Guardar e entrar na loja ${icon('arrow')}</button><button class="forgot-button" type="button" data-action="logout">Terminar sessão</button></form>`);$('#recovered-password-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,d=formData(f),b=f.querySelector('button:not([type="button"])');if(d.password!==d.confirmation)return formError(f,Error('As palavras-passe não coincidem.'));b.disabled=true;try{await api('password',{password:d.password});page='dashboard';await refresh();toast('Palavra-passe atualizada. Bem-vindo de volta!');}catch(err){formError(f,err);}finally{b.disabled=false;}};}
function installFilters(){if(['dashboard','account','sales'].includes(page))return;const wrappers=[...document.querySelectorAll('.table-wrap')];wrappers.forEach((wrap,index)=>{
 if(page==='products'&&index===0)return;
 const rows=[...wrap.querySelectorAll('tbody tr')];if(!rows.length)return;
 const records=page==='history'?state.sales:page==='activity'?state.audit:page==='cash'?state.shifts:page==='products'?state.purchases:state.users;
 const column={history:3,activity:0,users:3,cash:2,products:1}[page];
 const unique=[...new Set(rows.map(r=>page==='cash'?(r.children[2].textContent.trim()==='Aberto'?'Aberto':'Fechado'):r.children[column]?.textContent.trim()))].filter(Boolean).sort();
 const dated=page!=='users',id='filter-'+page+'-'+index;
 const f=filters[id]||{q:'',kind:'',start:'',end:'',active:''};filters[id]=f;
 const bar=document.createElement('div');bar.className='filter-bar';bar.innerHTML=`<div class="filter-query"><label for="${id}-q">Pesquisar</label><input id="${id}-q" placeholder="Escreva para filtrar…" value="${esc(f.q)}"></div><div><label for="${id}-kind">${({history:'Pagamento',users:'Perfil',activity:'Atividade',cash:'Estado',products:'Produto'})[page]}</label><select id="${id}-kind"><option value="">Todos</option>${unique.map(v=>`<option ${v===f.kind?'selected':''}>${esc(v)}</option>`).join('')}</select></div>${page==='users'?`<div><label for="${id}-active">Estado</label><select id="${id}-active"><option value="">Todos</option><option value="1" ${f.active==='1'?'selected':''}>Ativos</option><option value="0" ${f.active==='0'?'selected':''}>Inativos</option></select></div>`:''}${dated?`<div><label for="${id}-start">De</label><input id="${id}-start" type="date" value="${f.start}"></div><div><label for="${id}-end">Até</label><input id="${id}-end" type="date" value="${f.end}"></div>`:''}<button class="ghost small" type="button" data-clear-filters>Limpar filtros</button><span class="filter-count" aria-live="polite"></span>`;
 wrap.before(bar);const no=document.createElement('tr');no.innerHTML=`<td colspan="${rows[0].children.length}" class="empty">Nenhum registo corresponde aos filtros.</td>`;wrap.querySelector('tbody').append(no);
 function apply(){let count=0;rows.forEach((row,i)=>{const record=records[i],value=page==='cash'?(record?.closed?'Fechado':'Aberto'):row.children[column]?.textContent.trim();const timestamp=record?.created||record?.opened;const day=timestamp?new Date(new Date(timestamp.replace(' ','T')+'Z').getTime()+3600000).toISOString().slice(0,10):'';const visible=row.textContent.toLocaleLowerCase('pt').includes(f.q.toLocaleLowerCase('pt'))&&(!f.kind||f.kind===value)&&(!f.active||String(record?.active)===f.active)&&(!f.start||day>=f.start)&&(!f.end||day<=f.end);row.hidden=!visible;if(visible)count++;});no.hidden=!!count;bar.querySelector('.filter-count').textContent=`${count} de ${rows.length} registos carregados`;}
 for(const key of ['q','kind',...(page==='users'?['active']:[]),...(dated?['start','end']:[])]){const input=document.getElementById(id+'-'+key);input.addEventListener('input',()=>{f[key]=input.value;apply();});}
 bar.querySelector('[data-clear-filters]').onclick=()=>{for(const key of ['q','kind','start','end','active']){f[key]='';const input=document.getElementById(id+'-'+key);if(input)input.value='';}apply();};apply();
 });}
document.addEventListener('input',e=>{const el=e.target;if(!(el instanceof HTMLInputElement))return;
 if(el.hasAttribute('data-number')){const before=el.value.slice(0,el.selectionStart).replace(/\s/g,'').length;el.value=numericDisplay(el.value,Number(el.dataset.decimals||0));let logical=0,pos=0;for(;pos<el.value.length&&logical<before;pos++)if(el.value[pos]!==' ')logical++;el.setSelectionRange(pos,pos);const value=num(el.value),min=Number(el.dataset.min??0);el.setCustomValidity(el.value&&(!Number.isFinite(value)||value<min)?`Introduza um valor igual ou superior a ${min}.`:'');}
 if(el.hasAttribute('data-bi')){el.value=el.value.toUpperCase().replace(/[^A-Z0-9]/g,'').slice(0,14);el.setCustomValidity(el.value&&!/^\d{9}[A-Z]{2}\d{3}$/.test(el.value)?'O BI deve ter 9 algarismos, 2 letras e 3 algarismos. Exemplo: 009763932CA042.':'');}
 if(el.hasAttribute('data-person-name')){el.value=el.value.replace(/[^\p{L}\p{M} .’'-]/gu,'');}
 if(el.hasAttribute('data-phone')){el.value=el.value.replace(/[^+0-9 ()-]/g,'').replace(/(?!^)\+/g,'');}
 if(el.type==='email')el.setCustomValidity(el.value&& !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(el.value)?'Introduza um email válido, por exemplo nome@empresa.com.':'');
 if(el.hasAttribute('data-code'))el.value=el.value.replace(/\D/g,'').slice(0,6);
 if(el.hasAttribute('data-strong-password'))el.setCustomValidity(el.value&&!(el.value.length>=8&&/[A-Za-z]/.test(el.value)&&/\d/.test(el.value)&&/[^a-zA-Z0-9\s]/.test(el.value))?'Use pelo menos 8 caracteres, letras, números e um carácter especial.':'');
});

boot();
